'use client';
import { useId, useRef, useState, type CSSProperties, type KeyboardEvent, type ReactNode } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useIsoLayoutEffect } from '../lib/hooks';
import '../designme.css';
import './segmented-control.css';

export interface SegmentOption<T extends string = string> {
  value: T;
  label: ReactNode;
}

export interface SegmentedControlProps<T extends string = string> {
  options: SegmentOption<T>[];
  value?: T;
  defaultValue?: T;
  onValueChange?: (value: T) => void;
  /** Names the group for screen readers, like "View" */
  label: string;
  /** `tabs` (the default) when it switches a panel, `radio` when it sets an option */
  as?: 'tabs' | 'radio';
  /** Ties the tabs to their panel: put `id={`${id}-panel`}` and `aria-labelledby={`${id}-${value}`}` on the panel. Defaults to a generated id */
  id?: string;
  className?: string;
}

/** One choice from a few views or options, with a white knob that slides to the picked one. As tabs, the arrow keys
    move along and pick, and Home and End jump to the ends; as a radio group, the arrow keys do the same. */
export function SegmentedControl<T extends string = string>({ options, value, defaultValue, onValueChange, label, as = 'tabs', id, className }: SegmentedControlProps<T>) {
  const auto = useId();
  const base = id ?? 'dm-sgc' + auto.replace(/:/g, '');
  const [cur, setCur] = useControllable(value, (defaultValue ?? options[0]?.value) as T, onValueChange);
  const ref = useRef<HTMLDivElement>(null);
  const [knob, setKnob] = useState<CSSProperties>({ transition: 'none' });
  const first = useRef(true);
  // the knob takes the picked button's place and width, without sliding in on the first paint
  useIsoLayoutEffect(() => {
    const el = ref.current; if (!el) return;
    const place = () => {
      const b = el.querySelector<HTMLElement>('[data-on="true"]'); if (!b) return;
      setKnob({ left: b.offsetLeft, width: b.offsetWidth, ...(first.current ? { transition: 'none' } : {}) });
      if (first.current) requestAnimationFrame(() => { first.current = false; });
    };
    place();
    const ro = new ResizeObserver(place); ro.observe(el);
    return () => ro.disconnect();
  }, [cur, options.length]);

  const tabs = as === 'tabs';
  const onKey = (e: KeyboardEvent<HTMLDivElement>) => {
    const i = options.findIndex(o => o.value === cur);
    const to = ({ ArrowRight: i + 1, ArrowLeft: i - 1, Home: 0, End: options.length - 1 } as Record<string, number>)[e.key];
    if (to === undefined) return;
    e.preventDefault();
    const o = options[(to + options.length) % options.length];
    setCur(o.value);
    ref.current?.querySelector<HTMLElement>(`[data-v="${CSS.escape(o.value)}"]`)?.focus();
  };

  return (
    <div ref={ref} data-dm="" className={cx('dm-sgc-seg', className)} role={tabs ? 'tablist' : 'radiogroup'} aria-label={label} onKeyDown={onKey}>
      <span className="dm-sgc-k" style={knob} aria-hidden="true" />
      {options.map(o => {
        const on = o.value === cur;
        return (
          <button key={o.value} type="button" data-v={o.value} data-on={on} id={`${base}-${o.value}`} tabIndex={on ? 0 : -1}
            role={tabs ? 'tab' : 'radio'} {...(tabs ? { 'aria-selected': on, 'aria-controls': `${base}-panel` } : { 'aria-checked': on })}
            onClick={() => setCur(o.value)}>
            {o.label}
          </button>
        );
      })}
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Segmented control ---------- */
/* one choice from a few views of the same thing: the picked one sits on a white knob that slides to it. It is a tab
   list, so the arrow keys move along it and the panel under it changes with it */
.dm-sgc{width:100%;max-width:400px;margin:0 auto;padding:var(--dm-s-4);display:flex;flex-direction:column;gap:14px}
.dm-sgc-h{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-3);flex-wrap:wrap}
.dm-sgc-ht{display:flex;flex-direction:column;min-width:0}
.dm-sgc-ht b{font-weight:500;font-size:14px}
.dm-sgc-bar{display:flex;align-items:center;gap:2px;margin:-4px 0 -6px}
.dm-sgc-r{flex:1;min-width:0;font-size:13px;color:var(--dm-fg2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-sgc-bar .dm-ib{width:28px;height:28px}
.dm-sgc-bar .dm-pill{margin-right:var(--dm-s-1)}
.dm-sgc-seg{position:relative;display:inline-flex;padding:3px;border-radius:var(--dm-r-pill);background:var(--dm-chip);flex:none}
.dm-sgc-k{position:absolute;top:3px;bottom:3px;left:3px;width:0;border-radius:var(--dm-r-pill);background:var(--dm-surface);box-shadow:var(--dm-shadow);transition:left .42s var(--dm-ease),width .42s var(--dm-ease)}
.dm-sgc-seg button{position:relative;z-index:1;height:30px;padding:0 14px;border-radius:var(--dm-r-pill);font-size:13px;color:var(--dm-fg2);outline:0;transition:color .2s}
.dm-sgc-seg button[aria-selected="true"],.dm-sgc-seg button[aria-checked="true"]{color:var(--dm-fg)}
@media (hover:hover) and (pointer:fine){.dm-sgc-seg button:hover{color:var(--dm-fg)}}
.dm-sgc-seg button:focus-visible{box-shadow:0 0 0 2px var(--dm-focus)}
.dm-sgc-p{position:relative;height:178px;border-radius:var(--dm-r-in);outline:0}
.dm-sgc-p:focus-visible{box-shadow:0 0 0 2px var(--dm-focus)}
.dm-sgc-in{height:100%}
/* a new view crossfades over the one it replaces, so the panel is never empty between them */
.dm-sgc-in.dm-fresh{animation:dm-sgcin .24s var(--dm-ease) both}
.dm-sgc-in.dm-gone{position:absolute;inset:0;pointer-events:none;animation:dm-sgcout .24s var(--dm-ease) both}
@keyframes dm-sgcin{from{opacity:0;transform:translateY(4px)}}
@keyframes dm-sgcout{to{opacity:0}}
/* the day: its events in order */
.dm-sgc-day{display:flex;flex-direction:column;gap:6px}
.dm-sgc-ev{display:flex;align-items:center;gap:var(--dm-s-3);min-height:50px;padding:6px var(--dm-s-3);border-radius:var(--dm-r-in);background:var(--dm-row);font-size:13px}
.dm-sgc-ev i{width:3px;align-self:stretch;margin:var(--dm-s-1) 0;border-radius:2px;background:var(--dm-c);flex:none}
.dm-sgc-ev .dm-t{flex:1;min-width:0;display:flex;flex-direction:column}
.dm-sgc-ev .dm-t span{font-size:12px;color:var(--dm-muted)}
.dm-sgc-none{height:100%;display:grid;place-items:center;font-size:13px;color:var(--dm-muted)}
/* the week: the five working days, one roomy row each with its first event, a count of the rest, and today picked out */
.dm-sgc-wk{display:flex;flex-direction:column;gap:var(--dm-s-1)}
.dm-sgc-wr{display:flex;align-items:center;gap:var(--dm-s-3);width:100%;height:32px;padding:0 var(--dm-s-3);border-radius:var(--dm-r-sm);font-size:13px;text-align:left;transition:background var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.dm-sgc-wr:hover{background:var(--dm-row)}}
.dm-sgc-wr:focus-visible,.dm-sgc-mo .dm-d:focus-visible{outline:0;box-shadow:0 0 0 2px var(--dm-focus)}
.dm-sgc-wr .dm-d{width:52px;flex:none;color:var(--dm-muted)}
.dm-sgc-wr .dm-e{flex:1;min-width:0;display:flex;align-items:center;gap:var(--dm-s-2);white-space:nowrap}
.dm-sgc-wr .dm-e i{width:6px;height:6px;border-radius:50%;background:var(--dm-c);flex:none}
.dm-sgc-wr .dm-e span:last-child{min-width:0;overflow:hidden;text-overflow:ellipsis}
.dm-sgc-wr .dm-more{flex:none;font-size:12px;color:var(--dm-muted)}
.dm-sgc-wr.dm-none .dm-e{color:var(--dm-muted)}
.dm-sgc-wr.dm-now{background:var(--dm-sel)}
@media (hover:hover) and (pointer:fine){.dm-sgc-wr.dm-now:hover{background:var(--dm-sel)}}
.dm-sgc-wr.dm-now .dm-d{color:var(--dm-fg);font-weight:500}
/* the month: a dot on each day with something on */
.dm-sgc-mo{display:grid;grid-template-columns:repeat(7,1fr);gap:2px var(--dm-s-1);font-size:12px;text-align:center}
.dm-sgc-mo .dm-w{font-size:11px;color:var(--dm-muted);padding-bottom:2px}
.dm-sgc-mo .dm-d{position:relative;height:26px;display:grid;place-items:center;border-radius:var(--dm-r-sm);color:var(--dm-fg2);transition:background var(--dm-t-fast)}
.dm-sgc-mo.dm-r6 .dm-d{height:22px}
@media (hover:hover) and (pointer:fine){.dm-sgc-mo .dm-d:hover{background:var(--dm-row)}}
.dm-sgc-mo .dm-d.dm-on{background:var(--dm-surface);color:var(--dm-fg);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-on) 50%,transparent)}
.dm-sgc-mo .dm-d.dm-e::after{content:"";position:absolute;bottom:2px;left:50%;width:4px;height:4px;margin-left:-2px;border-radius:50%;background:var(--dm-accent-mark,var(--dm-accent))}
.dm-sgc-mo .dm-d.dm-now{background:var(--dm-ink);color:var(--dm-on-ink)}
@media (hover:hover) and (pointer:fine){.dm-sgc-mo .dm-d.dm-now:hover{background:var(--dm-ink);color:var(--dm-on-ink)}}
.dm-sgc-mo .dm-d.dm-now::after{background:var(--dm-on-ink)}
